∀ {cfg : RearmBarrier.Config} {probe : Nat}
  {t : RearmBarrier.Tree} {p : RearmBarrier.ProducerPhase}
  {V : Nat} {cs : Array RearmBarrier.ConsumerPhase},
  RearmBarrier.InvAt cfg probe t p V cs →
    RearmBarrier.ProbeOk cfg p probe

∀ {cfg : RearmBarrier.Config} {probe : Nat}
  {t : RearmBarrier.Tree} {p : RearmBarrier.ProducerPhase}
  {V : Nat} {cs : Array RearmBarrier.ConsumerPhase},
  RearmBarrier.InvAt cfg probe t p V cs →
    cs.size = cfg.workers

∀ {cs : Array RearmBarrier.ConsumerPhase} {id : Nat}
  {ph : RearmBarrier.ConsumerPhase},
  cs[id]? = some ph → RearmBarrier.phaseOf cs id = ph

∀ {cfg : RearmBarrier.Config} {probe : Nat}
  {t : RearmBarrier.Tree} {p : RearmBarrier.ProducerPhase}
  {V : Nat} {cs : Array RearmBarrier.ConsumerPhase},
  RearmBarrier.InvAt cfg probe t p V cs →
    RearmBarrier.Wf cfg.cluster cfg.workers t

∀ {cfg : RearmBarrier.Config} {probe : Nat}
  {t : RearmBarrier.Tree} {p : RearmBarrier.ProducerPhase}
  {V : Nat} {cs : Array RearmBarrier.ConsumerPhase},
  RearmBarrier.InvAt cfg probe t p V cs →
    RearmBarrier.TreeInv cfg V (RearmBarrier.phaseOf cs) t

∀ {cfg : RearmBarrier.Config} {probe : Nat}
  {t : RearmBarrier.Tree} {p : RearmBarrier.ProducerPhase}
  {V : Nat} {cs : Array RearmBarrier.ConsumerPhase},
  RearmBarrier.InvAt cfg probe t p V cs →
    p ≠ RearmBarrier.ProducerPhase.done → V < cfg.count

∀ {cfg : RearmBarrier.Config} {t : RearmBarrier.Tree}
  {c : RearmBarrier.Cursor} {v : Nat} {vc : RearmBarrier.VC}
  {ord : RearmBarrier.MemOrd} {t' : RearmBarrier.Tree}
  {vc' : RearmBarrier.VC} {rmw : RearmBarrier.Rmw}
  {next : RearmBarrier.Next},
  RearmBarrier.Tree.walk cfg t c v vc ord =
      RearmBarrier.WalkResult.ok t' vc' rmw next →
    ∀ (c' : RearmBarrier.Cursor),
      next = RearmBarrier.Next.continue c' →
        c'.path = c.path.dropLast ∧ c.path ≠ []

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree},
  RearmBarrier.Wf cfg.cluster cfg.workers t →
    RearmBarrier.TreeInv cfg V phase t →
      RearmBarrier.WalkInv cfg V phase t →
        ∀ {id : Nat} {c : RearmBarrier.Cursor}
          {next : RearmBarrier.Next},
          RearmBarrier.WalkFacts cfg V phase id c next →
            ∀ {vc : RearmBarrier.VC}
              {ord : RearmBarrier.MemOrd}
              {t' : RearmBarrier.Tree}
              {vc' : RearmBarrier.VC}
              {rmw : RearmBarrier.Rmw},
              RearmBarrier.Tree.walk cfg t c V vc ord =
                  RearmBarrier.WalkResult.ok t' vc' rmw
                    next →
                RearmBarrier.Completion.Steps
                  (RearmBarrier.absNode cfg V phase [] t)
                  (RearmBarrier.absNode cfg V
                    (RearmBarrier.upd phase id
                      (RearmBarrier.nextPhase cfg V next))
                    [] t')

∀ {cfg : RearmBarrier.Config} {probe : Nat}
  {t : RearmBarrier.Tree} {p : RearmBarrier.ProducerPhase}
  {V : Nat} {cs : Array RearmBarrier.ConsumerPhase},
  RearmBarrier.InvAt cfg probe t p V cs →
    probe ≤ 2 * cfg.count

∀ {cfg : RearmBarrier.Config} {s s' : RearmBarrier.State}
  {t : RearmBarrier.Thread}
  {ev : Option RearmBarrier.Event},
  RearmBarrier.step cfg s t =
      RearmBarrier.Outcome.step s' ev →
    s'.tree.window = s.tree.window

∀ {cfg : RearmBarrier.Config} {probe : Nat}
  {t : RearmBarrier.Tree} {p : RearmBarrier.ProducerPhase}
  {V : Nat} {cs : Array RearmBarrier.ConsumerPhase},
  RearmBarrier.InvAt cfg probe t p V cs →
    RearmBarrier.ProducerPhase.version cfg p = V

∀ {cfg : RearmBarrier.Config} {t : RearmBarrier.Tree}
  {c : RearmBarrier.Cursor} {v : Nat} {vc : RearmBarrier.VC}
  {ord : RearmBarrier.MemOrd} {t' : RearmBarrier.Tree}
  {vc' : RearmBarrier.VC} {rmw : RearmBarrier.Rmw}
  {next : RearmBarrier.Next},
  RearmBarrier.Wf cfg.cluster cfg.workers t →
    RearmBarrier.Tree.walk cfg t c v vc ord =
        RearmBarrier.WalkResult.ok t' vc' rmw next →
      RearmBarrier.Wf cfg.cluster cfg.workers t'

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree} {path : List Nat}
  {n : RearmBarrier.Tree},
  RearmBarrier.NodeInv cfg V phase t path n →
    RearmBarrier.deadAt cfg.workers t path n →
      n.version = 0 ∧
        n.finished = 0 ∧
          RearmBarrier.carriedTo cfg.workers path phase = 0

∀ {s : RearmBarrier.State} {ev : Option RearmBarrier.Event}
  {s_1 : RearmBarrier.State}
  {ev_1 : Option RearmBarrier.Event},
  RearmBarrier.Outcome.step s ev =
      RearmBarrier.Outcome.step s_1 ev_1 →
    s = s_1 ∧ ev = ev_1

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree} {path : List Nat}
  {n : RearmBarrier.Tree},
  RearmBarrier.NodeInv cfg V phase t path n →
    ∀ (id : Nat),
      id < cfg.workers →
        ∀ (v : Nat) (c : RearmBarrier.Cursor),
          phase id = RearmBarrier.ConsumerPhase.walk v c →
            c.path = path → v = n.version

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree} {path : List Nat}
  {n : RearmBarrier.Tree},
  RearmBarrier.NodeInv cfg V phase t path n →
    n.finished < n.size

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree} {path : List Nat}
  {n : RearmBarrier.Tree},
  RearmBarrier.NodeInv cfg V phase t path n →
    n.version ≤ V + 1

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree} {path : List Nat}
  {n : RearmBarrier.Tree},
  RearmBarrier.NodeInv cfg V phase t path n →
    ¬RearmBarrier.deadAt cfg.workers t path n →
      V ≤ n.version

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree} {clocks : Array RearmBarrier.VC}
  {mark : Nat → Nat},
  (∀ (j : Nat), mark j = 0) →
    RearmBarrier.TreeHb cfg V phase t clocks mark

∀ {t : RearmBarrier.Tree} {p q : List Nat}
  {n : RearmBarrier.Tree},
  t.get q = some n → p <+: q → ∃ m, t.get p = some m

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree},
  RearmBarrier.Wf cfg.cluster cfg.workers t →
    RearmBarrier.TreeInv cfg V phase t →
      ∀ {id : Nat} {c : RearmBarrier.Cursor},
        id < cfg.workers →
          phase id = RearmBarrier.ConsumerPhase.walk V c →
            V < cfg.count →
              ∀ {vc : RearmBarrier.VC}
                {ord : RearmBarrier.MemOrd}
                {t' : RearmBarrier.Tree}
                {vc' : RearmBarrier.VC}
                {rmw : RearmBarrier.Rmw}
                {next : RearmBarrier.Next},
                RearmBarrier.Tree.walk cfg t c V vc ord =
                    RearmBarrier.WalkResult.ok t' vc' rmw
                      next →
                  RearmBarrier.TreeInv cfg V
                    (RearmBarrier.upd phase id
                      (RearmBarrier.nextPhase cfg V next))
                    t'

∀ {tree : RearmBarrier.Tree} {vc : RearmBarrier.VC}
  {rmw : RearmBarrier.Rmw} {next : RearmBarrier.Next}
  {tree_1 : RearmBarrier.Tree} {vc_1 : RearmBarrier.VC}
  {rmw_1 : RearmBarrier.Rmw} {next_1 : RearmBarrier.Next},
  RearmBarrier.WalkResult.ok tree vc rmw next =
      RearmBarrier.WalkResult.ok tree_1 vc_1 rmw_1 next_1 →
    tree = tree_1 ∧ vc = vc_1 ∧ rmw = rmw_1 ∧ next = next_1

∀ {W : Nat} {t : RearmBarrier.Tree} {q : List Nat}
  {n : RearmBarrier.Tree},
  n.children = [] → ¬RearmBarrier.deadAt W t q n

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree},
  RearmBarrier.TreeInv cfg V phase t →
    RearmBarrier.WalkInv cfg V phase t →
      ∀ {id : Nat} {c : RearmBarrier.Cursor},
        id < cfg.workers →
          phase id = RearmBarrier.ConsumerPhase.walk V c →
            ∀ {vc : RearmBarrier.VC}
              {ord : RearmBarrier.MemOrd}
              {t' : RearmBarrier.Tree}
              {vc' : RearmBarrier.VC}
              {rmw : RearmBarrier.Rmw}
              {next : RearmBarrier.Next},
              RearmBarrier.Tree.walk cfg t c V vc ord =
                  RearmBarrier.WalkResult.ok t' vc' rmw
                    next →
                RearmBarrier.WalkInv cfg V
                  (RearmBarrier.upd phase id
                    (RearmBarrier.nextPhase cfg V next))
                  t'

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree} {clocks : Array RearmBarrier.VC}
  {mark : Nat → Nat},
  (∀ (j : Nat), ¬RearmBarrier.PastLeaf cfg V phase j) →
    RearmBarrier.TreeHb cfg V phase t clocks mark

∀ {cfg : RearmBarrier.Config} {s s' : RearmBarrier.State}
  {t : RearmBarrier.Thread}
  {ev : Option RearmBarrier.Event},
  RearmBarrier.step cfg s t =
      RearmBarrier.Outcome.step s' ev →
    s.probe ≤ s'.probe

∀ {cfg : RearmBarrier.Config} {s s' : RearmBarrier.State}
  {t : RearmBarrier.Thread}
  {ev : Option RearmBarrier.Event},
  RearmBarrier.step cfg s t =
      RearmBarrier.Outcome.step s' ev →
    s'.probe = s.probe → s'.probeRel = s.probeRel

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {next : RearmBarrier.Next} {v' : Nat}
  {c' : RearmBarrier.Cursor},
  RearmBarrier.nextPhase cfg V next =
      RearmBarrier.ConsumerPhase.walk v' c' →
    next = RearmBarrier.Next.continue c' ∧ v' = V

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase} {id : Nat}
  {c : RearmBarrier.Cursor} {next : RearmBarrier.Next},
  RearmBarrier.WalkFacts cfg V phase id c next →
    id < cfg.workers

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase} {id : Nat}
  {c : RearmBarrier.Cursor} {next : RearmBarrier.Next},
  RearmBarrier.WalkFacts cfg V phase id c next →
    c.path <+: (RearmBarrier.Cursor.start cfg id).path

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase} {id : Nat}
  {c : RearmBarrier.Cursor} {next : RearmBarrier.Next},
  RearmBarrier.WalkFacts cfg V phase id c next →
    phase id = RearmBarrier.ConsumerPhase.walk V c

∀ {finished : Nat} {pending : Bool}
  {clock : RearmBarrier.Completion.Clock}
  {children : List RearmBarrier.Completion.Node}
  {finished_1 : Nat} {pending_1 : Bool}
  {clock_1 : RearmBarrier.Completion.Clock}
  {children_1 : List RearmBarrier.Completion.Node},
  RearmBarrier.Completion.Node.mk finished pending clock
        children =
      RearmBarrier.Completion.Node.mk finished_1 pending_1
        clock_1 children_1 →
    finished = finished_1 ∧
      pending = pending_1 ∧
        clock = clock_1 ∧ children = children_1

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase} {id : Nat}
  {c : RearmBarrier.Cursor} {next : RearmBarrier.Next},
  RearmBarrier.WalkFacts cfg V phase id c next →
    V < cfg.count

∀ {cfg : RearmBarrier.Config} {probe : Nat}
  {t : RearmBarrier.Tree} {p : RearmBarrier.ProducerPhase}
  {V : Nat} {cs : Array RearmBarrier.ConsumerPhase},
  RearmBarrier.InvAt cfg probe t p V cs → V ≤ cfg.count

∀ {cfg : RearmBarrier.Config} {probe : Nat}
  {t : RearmBarrier.Tree} {p : RearmBarrier.ProducerPhase}
  {V : Nat} {cs : Array RearmBarrier.ConsumerPhase},
  RearmBarrier.InvAt cfg probe t p V cs →
    probe ≠ 2 * V → V < cfg.count

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t : RearmBarrier.Tree} {clocks : Array RearmBarrier.VC}
  {mark mark' : Nat → Nat},
  RearmBarrier.TreeHb cfg V phase t clocks mark →
    (∀ (j : Nat),
        RearmBarrier.PastLeaf cfg V phase j →
          mark' j = mark j) →
      RearmBarrier.TreeHb cfg V phase t clocks mark'

∀ {s s' : RearmBarrier.State} {t : Nat}
  {a : RearmBarrier.Access}
  {k : RearmBarrier.State → RearmBarrier.Outcome}
  {ev : Option RearmBarrier.Event},
  RearmBarrier.Outcome.accessing s t a k =
      RearmBarrier.Outcome.step s' ev →
    ∃ s₁,
      s₁.probeRel = s.probeRel ∧
        k s₁ = RearmBarrier.Outcome.step s' ev

∀ {cfg : RearmBarrier.Config} {V : Nat}
  {phase : Nat → RearmBarrier.ConsumerPhase}
  {t t' : RearmBarrier.Tree}
  {clocks : Array RearmBarrier.VC} {mark mark' : Nat → Nat},
  RearmBarrier.TreeHb cfg V phase t clocks mark →
    t' = t →
      (∀ (j : Nat), mark' j = mark j) →
        RearmBarrier.TreeHb cfg V phase t' clocks mark'

∀ {s s' : RearmBarrier.State} {t : Nat}
  {a : RearmBarrier.Access},
  s.access t a = Except.ok s' → s'.probeRel = s.probeRel
